messages.content:
{
  "early_commentary": {
    "label": "劉孝標注",
    "notes": [
      {
        "ref": "L01",
        "text": "(夀琅邪人祖正尚書郎父彬衛將軍彭之/虎㹠王彭之小字也王氏譜曰彭之字安)"
      },
      {
        "ref": "L02",
        "text": "(三弟年二十而頭須皓白時人謂之王白須少有局/仕至黄門郎虎犢彪之小字也彪之字叔虎彭之第)"
      },
      {
        "ref": "L03",
        "text": "(左光禄大夫/榦之稱累遷至)"
      }
    ]
  },
  "frozen_questions": [
    {
      "gap": "缺少『虎㹠虎犢』是具體人物小字還是比喻的說明，若不確定，無法判斷王導是在點名還是在泛論子姪。",
      "question_id": "Q1",
      "story_span": "云虎㹠虎犢"
    },
    {
      "gap": "缺少『還其所如』的語義或出處，若不理解此語，無法把握王導感嘆的落點與褒貶邏輯。",
      "question_id": "Q2",
      "story_span": "還其所如"
    },
    {
      "gap": "缺少王導與王右軍的宗族關係及通信語境，影響理解為何向王右軍傾訴自家子姪不成器，以及此事何以入『輕詆』。",
      "question_id": "Q3",
      "story_span": "王右軍在南丞相與書"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": [
      {
        "layer": "collation_note",
        "ref": "J01",
        "source_labels": [],
        "speaker": null,
        "text": "注兩「鬚」字，景宋本俱作「須」。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J02",
        "source_labels": [],
        "speaker": "余嘉錫",
        "text": "〔一〕 程炎震云：「王導卒於咸康五年，彪之年三十四。此蓋彪之初為郎時，右軍當在江州。」嘉錫案：言彭之、彪之，生長高門，而才質凡下，羊質虎皮，恰如其名也。嘉錫又案：言彭之真豚犬之流，彪之初生之犢，二人之才正如其小字耳。"
      }
    ]
  },
  "primary_text": {
    "label": "世說新語正文",
    "text": "王右軍在南丞相與書毎歎子姪不令云虎㹠虎犢\n還其所如"
  },
  "story_id": "26-qingdi-008"
}
